oracle.script:
cat > filter.py <<'EOF'
import json
out = []
for ln in open('events.jsonl'):
    try:
        e = json.loads(ln)
    except json.JSONDecodeError:
        continue
    if e.get('level') == 'error':
        out.append(ln.rstrip('\n'))
open('errors.jsonl','w').write('\n'.join(out) + '\n')
EOF
python3 filter.py
